CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE sessions(id TEXT PRIMARY KEY, started_at TEXT NOT NULL, ended_at TEXT, workspace TEXT NOT NULL, environment_json TEXT, outcome TEXT);
CREATE TABLE functions(id TEXT PRIMARY KEY, binary_path TEXT NOT NULL, original_va INTEGER, name TEXT, reconstructed_signature TEXT, recovery_status TEXT);
CREATE TABLE operations(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), function_id TEXT REFERENCES functions(id), started_at TEXT NOT NULL, ended_at TEXT, stage TEXT, tool TEXT, operation TEXT, input_path TEXT, command_json TEXT, status TEXT NOT NULL, duration_ms INTEGER, exit_code INTEGER, stdout TEXT, stderr TEXT, validation_status TEXT);
CREATE TABLE events(id TEXT PRIMARY KEY, timestamp_utc TEXT NOT NULL, session_id TEXT NOT NULL REFERENCES sessions(id), operation_id TEXT REFERENCES operations(id), function_id TEXT REFERENCES functions(id), severity TEXT NOT NULL CHECK(severity IN ('DEBUG','INFO','WARNING','ERROR','CRITICAL')), stage TEXT, tool TEXT, operation TEXT, input_path TEXT, function_name TEXT, original_va INTEGER, error_category TEXT, error_code TEXT, message TEXT, stack_trace TEXT, exit_code INTEGER, stdout TEXT, stderr TEXT, context_json TEXT, fingerprint TEXT, recovery_action TEXT, outcome TEXT, validation_status TEXT);
CREATE INDEX events_fingerprint ON events(fingerprint);
CREATE INDEX events_session ON events(session_id, timestamp_utc);
CREATE TABLE recovery_attempts(id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), operation_id TEXT REFERENCES operations(id), attempted_at TEXT NOT NULL, action TEXT NOT NULL, attempt_number INTEGER NOT NULL, outcome TEXT, validation_status TEXT);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), operation_id TEXT REFERENCES operations(id), path TEXT NOT NULL, kind TEXT, sha256 TEXT, provenance_json TEXT, created_at TEXT NOT NULL);
